const input=$json.body??$json;
const s=input.negotiation_strategy??{};
const decision=String(s.decision||input.decision||"").toLowerCase();
const mao=Number(s.dynamic_mao??input.dynamic_mao??input.adjusted_mao??input.mao);
const counter=Number(s.counteroffer_amount??input.counteroffer_amount);
const asking=Number(input.asking_price);
const validMao=Number.isFinite(mao)&&mao>0;
const validCounter=Number.isFinite(counter)&&counter>0;
const channel=String(input.channel||input.preferred_channel||"").toLowerCase();
const recipient=String(input.recipient||input.phone||input.email||"").trim();
const dnc=Boolean(input.dnc||input.do_not_contact);
const blockers=Array.isArray(input.blockers)?input.blockers:[];
let status="offer_generation_review_required",offerState="needs_review",nextWorkflow="WF-126",human=true,reason="offer generation requires review";
let offerPrice=null,negotiationTarget=null;
if(dnc){status="blocked_dnc";offerState="blocked";reason="seller is marked do-not-contact";}
else if(blockers.length){status="blocked";offerState="blocked";reason="active blockers present";}
else if(!validMao){status="mao_missing";offerState="needs_review";reason="dynamic MAO is missing or invalid";}
else if(decision==="counteroffer_near_mao"&&validCounter){
  offerPrice=Math.min(counter,mao);
  negotiationTarget=Math.min(Math.max(Math.round((offerPrice+mao)/2),offerPrice),mao);
  status="revised_offer_ready";offerState="ready";nextWorkflow="WF-294";reason="revised offer generated inside protected dynamic MAO";
}
else if(decision==="counteroffer_within_mao"&&validCounter){
  offerPrice=counter;negotiationTarget=counter;
  status="acceptance_or_contract_ready";offerState="contract_path";nextWorkflow="WF-293";reason="counteroffer is already within dynamic MAO; no upward offer is authorized";
}
else if(decision==="counteroffer_above_mao"){
  status="above_mao_blocked";offerState="blocked";nextWorkflow="WF-294";reason="no revised offer may exceed dynamic MAO";
}
else if(decision==="accepted"){
  status="contract_ready";offerState="contract_path";nextWorkflow="WF-293";reason="seller accepted; proceed to contract decision";
}
else if(decision==="rejected"||decision==="reengage"){
  status="reengagement_ready";offerState="reengagement";nextWorkflow="WF-294";reason="seller requires controlled re-engagement";
}
else{
  status="needs_review";offerState="needs_review";reason="negotiation state does not authorize automated offer generation";
}
const channelReady=["sms","email"].includes(channel)&&recipient.length>0;
if(offerState==="ready"&&!channelReady){status="dispatch_identity_missing";offerState="needs_review";nextWorkflow="WF-126";reason="revised offer is ready but valid channel/recipient is missing";}
if(offerPrice!==null&&offerPrice>mao){status="above_mao_blocked";offerState="blocked";nextWorkflow="WF-126";reason="hard guardrail prevented an offer above dynamic MAO";}
const idempotencyKey=input.idempotency_key||`wf-298:${input.deal_id||"unknown"}:${input.dispatch_id||"none"}:${input.version||1}`;
return [{json:{...input,workflow:"WF-298",workflow_name:"Negotiation Strategy → Revised Offer Generation & Seller Dispatch Controller",status,revised_offer:{state:offerState,offer_price:offerPrice,negotiation_target:negotiationTarget,dynamic_mao:validMao?mao:null,counteroffer_amount:validCounter?counter:null,asking_price:Number.isFinite(asking)?asking:null,channel:channelReady?channel:null,recipient:channelReady?recipient:null,reason,guardrail:"HARD_PROTECT_DYNAMIC_MAO"},next_workflow:nextWorkflow,human_review_required:human,audit:{event_type:"revised_offer_generation_dispatch",idempotency_key:idempotencyKey}}}];
